  "risk": {
    "level": "high",
    "touches": [
      "wallet",
      "wallet_storage",
      "rpc_api"
    ],
    "why": "Mistakes in wallet descriptor serialization or multipath association logic could corrupt wallet database records or lead to incorrect address derivation and missing funds."
  }
}
